MediaStoreMetadata::MediaStoreMetadata() : tag_(Tag::kUnknown) {
  data_.unknown = uint8_t();
}

MediaStoreMetadata::~MediaStoreMetadata() {
  DestroyActive();
}


void MediaStoreMetadata::set_unknown(
    uint8_t unknown) {
  if (tag_ != Tag::kUnknown) {
    DestroyActive();
    tag_ = Tag::kUnknown;
  }
  data_.unknown = unknown;
}
void MediaStoreMetadata::set_download(
    MediaStoreDownloadMetadataPtr download) {
  if (tag_ == Tag::kDownload) {
    *(data_.download) = std::move(download);
  } else {
    DestroyActive();
    tag_ = Tag::kDownload;
    data_.download = new MediaStoreDownloadMetadataPtr(
        std::move(download));
  }
}

void MediaStoreMetadata::DestroyActive() {
  switch (tag_) {

    case Tag::kUnknown:

      break;
    case Tag::kDownload:

      delete data_.download;
      break;
  }
}

bool MediaStoreMetadata::Validate(
    const void* data,
    mojo::internal::ValidationContext* validation_context) {
  return Data_::Validate(data, validation_context, false);
}
