// static
bool UnionTraits<::arc::mojom::MediaStoreMetadata::DataView, ::arc::mojom::MediaStoreMetadataPtr>::Read(
    ::arc::mojom::MediaStoreMetadata::DataView input,
    ::arc::mojom::MediaStoreMetadataPtr* output) {
  using UnionType = ::arc::mojom::MediaStoreMetadata;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kUnknown: {
      *output = UnionType::NewUnknown(input.unknown());
      break;
    }
    case Tag::kDownload: {
      ::arc::mojom::MediaStoreDownloadMetadataPtr result_download;
      if (!input.ReadDownload(&result_download))
        return false;

      *output = UnionType::NewDownload(
          std::move(result_download));
      break;
    }
    default:

      *output = UnionType::NewUnknown({});
      return true;
  }
  return true;
}

